import { useState } from "react";
import "./Component.css";

export type Card = { id: string; text: string };
export type Props = { cards: Card[]; onFinish: (ids: string[]) => void };

export function Component({ cards, onFinish }: Props) {
  const [deck] = useState(() => [...cards]);
  const [completed, setCompleted] = useState(0);
  const done = completed >= deck.length;

  function next() {
    if (done) return;
    const nextCompleted = completed + 1;
    setCompleted(nextCompleted);
    if (nextCompleted === deck.length) {
      onFinish(deck.map((card) => card.id));
    }
  }

  function restart() {
    setCompleted(0);
  }

  return (
    <div data-testid="panel" className="question-deck-panel">
      <output aria-label="Current">{deck[completed]?.text ?? "Done"}</output>
      <output aria-label="Completed">{completed}</output>
      <button type="button" onClick={next} disabled={done}>Next</button>
      <button type="button" onClick={restart}>Restart</button>
    </div>
  );
}
```

